// C: Conditional Branching (High Level)
int check(int x) {
    if (x > 100) {
        return 1;
    } else if (x == 100) {
        return 0;
    }
    // Implicit fall-through
    return -1;
}

// Assembly (x64): Translating 'if/else' via Jumps
; Input x is in RDI
check:
    cmp rdi, 100        ; Compare x to 100
    jg  L_GREATER       ; Jump if Greater

    cmp rdi, 100        ; Check equality
    je  L_EQUAL         ; Jump if Equal

    mov rax, -1         ; Default return -1
    jmp L_END

L_GREATER:
    mov rax, 1
    jmp L_END

L_EQUAL:
    mov rax, 0

L_END:
    ret


// C: Iteration (High Level 'while')
int sum_to_n(int n) {
    int i = 0;
    int sum = 0;
    while (i < n) {
        sum += i;
        i++;
    }
    return sum;
}

// Assembly (x64): Translating 'while' via Backwards Jumps
; Loop setup: RDI = n, RSI = i=0, RAX = sum=0
L_LOOP_START:
    cmp rsi, rdi        ; while (i < n)
    jge L_LOOP_END      ; Jump if Greater/Equal (Exit condition)
    add rax, rsi        ; sum += i
    inc rsi             ; i++
    jmp L_LOOP_START    ; Unconditional jump back to condition

L_LOOP_END:
    ret                 ; RAX contains sum

// C: Unconditional Jump (goto)
void error_handler(int status) {
    if (status != 0) goto HANDLE_ERROR;

    // Normal processing continues
    goto CLEANUP;

HANDLE_ERROR:
    // Handle error path
    status = -1;

CLEANUP:
    // Finalizing logic
    status = 0;
}
